    // Optimized schedule
    //
    // Goal:
    //   - Keep algorithm identical to the original 3mm C kernel.
    //   - Exploit data locality with cache-friendly loop orders.
    //   - Use SIMD vectorization on the contiguous (x) dimension.
    //   - Parallelize across the outer (row) dimension for multicore.
    //
    // Notes on layout:
    //   - All matrices are stored column-major with x-fastest.
    //   - For E(j, i), j (x) is contiguous in memory.
    //   - For F(l, j), l (x) is contiguous in memory.
    //   - For G_func(l, i), l (x) is contiguous in memory.
    //
    // We therefore:
    //   - Vectorize across x (j or l).
    //   - Parallelize across y (i or j), which are large and independent.
    //   - Reorder reduction loops so that for each (row, reduction-index)
    //     we stream a full contiguous row/column in x.
    // ------------------------------------------------------------------

    constexpr int vec_width = 8;  // tuned for typical AVX-style hardware

    // E(i,j,k):
    //   Pure definition: for each (i,j) set E(i,j) = 0
    //   Update: for each k accumulate A(i,k) * B(k,j)
    //
    // Loop structure after scheduling (conceptual):
    //   // pure
    //   parallel for i:
    //     for j (vectorized):
    //       E(j,i) = 0
    //
    //   // update
    //   parallel for i:
    //     for k in 0..nk-1:
    //       for j (vectorized):
    //         E(j,i) += A(k,i) * B(j,k);
    //
    // This has good locality:
    //   - For fixed (i,k) we stream B(j,k) contiguously across j.
    //   - A(k,i) is reused across that inner vector.
    E
        .compute_root()
        .reorder(j, i)            // x = j innermost
        .vectorize(j, vec_width)  // SIMD across contiguous j
        .parallel(i);             // parallel across rows

    E.update()
        .reorder(j, rAB, i)       // i outer, then k, then j innermost
        .vectorize(j, vec_width)
        .parallel(i);

    // F(i,j,k): analogous to E, but for C*D.
    //
    // Conceptual loops:
    //   parallel for j:
    //     for l (vectorized):
    //       F(l,j) = 0;
    //
    //   parallel for j:
    //     for m in 0..nm-1:
    //       for l (vectorized):
    //         F(l,j) += C(m,j) * D(l,m);
    //
    // Again, for fixed (j,m) we stream D(l,m) contiguously across l,
    // reusing C(m,j) across the inner vector.
    F
        .compute_root()
        .reorder(l, j)            // x = l innermost
        .vectorize(l, vec_width)
        .parallel(j);             // parallel across rows (original nj)

    F.update()
        .reorder(l, rCD, j)       // j outer, then m, then l
        .vectorize(l, vec_width)
        .parallel(j);

    // G(i,j,k): G = E * F
    //
    // We choose a loop nest that, for each (i,k), streams a row of F
    // contiguously in l and vectorizes over l:
    //
    //   parallel for i:
    //     for k in 0..nj-1:
    //       scalar e = E(k,i);
    //       for l (vectorized):
    //         G(l,i) += e * F(l,k);
    //
    // This uses:
    //   - good cache reuse for E(k,i) (scalar broadcast across l),
    //   - streaming contiguous slices of F(l,k) and G(l,i) in x.
    G_func
        .compute_root()
        .reorder(l, i)            // x = l innermost
        .vectorize(l, vec_width)
        .parallel(i);             // parallel across rows (original ni)

    G_func.update()
        .reorder(l, rEF, i)       // i outer, then k (rEF), then l innermost
        .vectorize(l, vec_width)
        .parallel(i);

    // Compile the kernel to machine code.
    G_func.compile_jit();

    // Measure execution time (kernel only).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize G_func into Buffer G (shape nl x ni).
    G_func.realize(G);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix G to stderr.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // G[ii][jj] in C => G(jj, ii) in Halide
                std::cerr << G(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds to stdout with 6 decimal places,
    // matching the style of the gemm.cpp example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
