 *
 * Original C layout (row-major):
 *   A[ni][nk]
 *   B[nk][nj]
 *   C[nj][nm]
 *   D[nm][nl]
 *
 * Optimized Halide layout (column-major / x-fastest):
 *   A(k, i) => A[i][k]   -> Buffer A(nk, ni)
 *   B(k, j) => B[k][j]   -> Buffer B(nk, nj)
 *   C(m, j) => C[j][m]   -> Buffer C(nm, nj)
 *   D(m, l) => D[m][l]   -> Buffer D(nm, nl)
 *
 * This layout is chosen so that in all three matrix multiplications
 * the reduction index is the x-dimension (fastest varying), which
 * gives contiguous memory access for both input matrices.
 */
static void init_array(int ni, int nj, int nk, int nl, int nm,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> D) {
    Var i("i"), j("j"), k("k"), l("l"), m("m");

    Func init_A("init_A"), init_B("init_B"), init_C("init_C"), init_D("init_D");

    // Original C:
    //   A[i][j] = (DATA_TYPE) ((i*j + 1) % ni) / (5*ni);
    // Mapping: A(k, i) == A[i][k]
    Expr denom_A = cast<num_t>(5 * ni);
    init_A(k, i) = cast<num_t>((i * k + 1) % ni) / denom_A;

    // Original C:
    //   B[i][j] = (DATA_TYPE) ((i*(j+1) + 2) % nj) / (5*nj);
    // Mapping: B(k, j) == B[i][j] with i -> k, j -> j
    Expr denom_B = cast<num_t>(5 * nj);
    init_B(k, j) = cast<num_t>((k * (j + 1) + 2) % nj) / denom_B;

    // Original C:
    //   C[i][j] = (DATA_TYPE) (i*(j+3) % nl) / (5*nl);
    // Mapping: C(m, j) == C[j][m] with i -> j, j -> m
    Expr denom_C = cast<num_t>(5 * nl);
    init_C(m, j) = cast<num_t>((j * (m + 3) % nl)) / denom_C;

    // Original C:
    //   D[i][j] = (DATA_TYPE) ((i*(j+2) + 2) % nk) / (5*nk);
    // Mapping: D(m, l) == D[i][j] with i -> m, j -> l
    Expr denom_D = cast<num_t>(5 * nk);
    init_D(m, l) = cast<num_t>((m * (l + 2) + 2) % nk) / denom_D;

