    // Problem sizes from 3mm.hpp
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;
    int nm = NM;

    // Allocate Buffers corresponding to the original C arrays.
    //
    // C layout: A[ni][nk] -> Halide: A(k, i)  -> A(nk, ni)
    //           B[nk][nj] -> Halide: B(k, j)  -> B(nk, nj)
    //           C[nj][nm] -> Halide: C(m, j)  -> C(nm, nj)
    //           D[nm][nl] -> Halide: D(m, l)  -> D(nm, nl)
    //           G[ni][nl] -> Halide: G(l, i)  -> G(nl, ni)
