    //
    // 1) E := A * B
    // C: E[ni][nj] = sum_{k=0..nk-1} A[i][k] * B[k][j]
    // Halide: E(j, i)  (x = column j, y = row i)
    Func E("E");
    E(j, i) = cast<num_t>(0);
    E(j, i) += A_param(rAB, i) * B_param(rAB, j);
    // A_param(rAB, i) => A(k, i) == A[i][k]
    // B_param(rAB, j) => B(k, j) == B[k][j]

    // 2) F := C * D
    // C: F[nj][nl] = sum_{k=0..nm-1} C[i][k] * D[k][j]
    // Halide: F(l, j)  (x = column l, y = row j)
    Func F("F");
    F(l, j) = cast<num_t>(0);
    F(l, j) += C_param(rCD, j) * D_param(rCD, l);
    // C_param(rCD, j) => C(m, j) == C[j][m]
    // D_param(rCD, l) => D(m, l) == D[m][l]

    // 3) G := E * F
    // C: G[ni][nl] = sum_{k=0..nj-1} E[i][k] * F[k][j]
    // Halide: G_func(l, i)  (x = column l, y = row i)
    Func G_func("G");
    G_func(l, i) = cast<num_t>(0);
    G_func(l, i) += E(rEF, i) * F(l, rEF);
    // E(rEF, i) => E[j][i]
    // F(l, rEF) => F[j][l]

    // ------------------------------------------------------------------
    // Optimized schedule
    //
    // Goal:
    //   - Keep arithmetic identical to the 3mm C kernel (no algorithmic
    //     changes, just loop reordering over non-reduction dims).
    //   - Make the reduction dimension (k) the x-dimension for all inputs
    //     to get contiguous accesses.
    //   - Parallelize over output rows.
    //   - Vectorize across columns.
    // ------------------------------------------------------------------

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // E(j, i): j is x (fast), i is y (slow).
    // Pure definition: zero-initialize E.
    E.compute_root()
        .parallel(i)          // rows of E
        .vectorize(j, vec_width);

    // Update definition: for each (i,j) accumulate over k.
    // Default loop nest is: for i, for j, for rAB.
    // Vectorize across j (contiguous in memory), parallelize across i.
    E.update()
        .parallel(i)
        .vectorize(j, vec_width);

    // F(l, j): l is x (fast), j is y (slow).
    F.compute_root()
        .parallel(j)          // rows of F
        .vectorize(l, vec_width);

    F.update()
        .parallel(j)
        .vectorize(l, vec_width);

    // G(l, i): l is x (fast), i is y (slow).
    // G is the final result; we parallelize across rows (i), and
    // vectorize across columns (l).
    G_func.compute_root()
        .parallel(i)
        .vectorize(l, vec_width);

    G_func.update()
        .parallel(i)
        .vectorize(l, vec_width);

    // Compile the kernel to machine code.
    G_func.compile_jit(target);

    // Measure execution time (kernel only).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize G_func into Buffer G (shape nl x ni).
    G_func.realize(G);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix G to stderr.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // G[ii][jj] in C => G(jj, ii) in Halide
                std::cerr << G(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds to stdout with 6 decimal places,
    // matching the style of the gemm.cpp example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
