    //
    // Storage layout:
    //   A_param(k, i) -> A(nk, ni): k is x (contiguous), i is y.
    //   B_param(j, k) -> B(nj, nk): j is x (contiguous), k is y.
    //   E(j, i)       -> E(nj, ni): j is x, i is y.
