    E(j, i) += A_param(rAB, i) * B_param(j, rAB);

    // 2) F := C * D
    // C: F[nj][nl] = sum_{k=0..nm-1} C[i][k] * D[k][j]
    // Halide: F(l, j)
    Func F("F");
    F(l, j) = cast<num_t>(0);
    F(l, j) += C_param(rCD, j) * D_param(l, rCD);

    // 3) G := E * F
    // C: G[ni][nl] = sum_{k=0..nj-1} E[i][k] * F[k][j]
    // Halide: G_func(l, i)
    Func G_func("G");
    G_func(l, i) = cast<num_t>(0);
    G_func(l, i) += E(rEF, i) * F(l, rEF);

    // ------------------------------------------------------------------
    // Optimized schedule
    //
    // Goals:
    //   - Exploit 32-core parallelism across rows/tiles.
    //   - Vectorize along contiguous x-dimension where possible.
    //   - Tile the final multiply G to improve locality in E and F.
    //   - Keep the math identical; we only change loop ordering.
    // ------------------------------------------------------------------

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // -------------------
    // Schedule for E = A*B
    // -------------------
    //
    // Layout:
    //   E(j, i) with shape [nj, ni], x=j contiguous, y=i stride=nj.
    // Access pattern in update:
    //   E(j, i) += A(rAB, i) * B(j, rAB)
    //   - For fixed (i, rAB), j is contiguous in E and B.
    //
    // Strategy:
    //   - Parallelize across rows 'i' (independent output rows).
    //   - Vectorize across x-dimension 'j'.
    //   - Make j innermost in the update so vectorization hits
    //     contiguous memory in E and (partially) in B.
    E.compute_root()
        .bound(j, 0, nj).bound(i, 0, ni)  // help bounds inference
        .reorder(j, i)                    // j innermost
        .vectorize(j, vec_width)
        .parallel(i);

    E.update()
        // Loop order (outermost -> innermost): i, rAB, j
        // given arguments from innermost to outermost:
        .reorder(j, rAB, i)
        .vectorize(j, vec_width)
        .parallel(i);

    // -------------------
    // Schedule for F = C*D
    // -------------------
    //
    // Layout:
    //   F(l, j) with shape [nl, nj], x=l contiguous, y=j stride=nl.
    // Access pattern in update:
    //   F(l, j) += C(rCD, j) * D(l, rCD)
    //   - For fixed (j, rCD), l is contiguous in F and D.
    //
    // Strategy:
    //   - Parallelize across rows 'j'.
    //   - Vectorize across x-dimension 'l'.
    F.compute_root()
        .bound(l, 0, nl).bound(j, 0, nj)
        .reorder(l, j)
        .vectorize(l, vec_width)
        .parallel(j);

    F.update()
        // Loop order (outermost -> innermost): j, rCD, l
        .reorder(l, rCD, j)
        .vectorize(l, vec_width)
        .parallel(j);

    // --------------------------
    // Schedule for G = E*F (3rd mm)
    // --------------------------
    //
    // Layout:
    //   G_func(l, i) with shape [nl, ni].
    //
    // Naive (conceptual) loops:
    //   for i in [0, ni)
    //     for l in [0, nl)
    //       sum_{k in [0, nj)} E(k, i) * F(l, k)
    //
    // To improve locality we tile G over (l, i) and, inside each tile,
    // iterate over the reduction dimension rEF in the outer part of the
    // inner loop nest:
    //
    //   for each tile (io, lo)
    //     for k in [0, nj)    // rEF
    //       for ii, li inside tile
    //         G_tile(li, ii) += E(k, ii) * F(li, k)
    //
    // This reuses:
    //   - The row E(k, ii) across all columns li in the tile
    //   - The row F(li, k) across all rows ii in the tile
    //
    Var lo("lo"), io("io"), li("li"), ii("ii");

    const int tile_l = 32;  // tile size in l (columns)
    const int tile_i = 32;  // tile size in i (rows)

    // Pure definition: tile and parallelize over outer tiles,
    // vectorize across contiguous l inside each tile.
    G_func.compute_root()
        .bound(l, 0, nl).bound(i, 0, ni)
        .tile(l, i, lo, io, li, ii, tile_l, tile_i)
        // After tile(), default loop order is io, lo, ii, li.
        // We keep that for the pure definition, but make li innermost.
        .reorder(li, ii, lo, io)
        .vectorize(li, vec_width)
        .parallel(io);

    // Update definition: same tiling, but we explicitly reorder to
    // make the reduction rEF just outside the innermost (ii, li)
    // loops. This gives a per-tile, k-major ordering:
    //
    //   for io
    //     for lo
    //       for rEF
    //         for ii
    //           for li
    //
    // which improves reuse of E and F within a tile.
    G_func.update()
        .reorder(li, ii, rEF, lo, io)  // arguments: innermost -> outermost
        .vectorize(li, vec_width)
        .parallel(io);

    // Compile the kernel to machine code for the current host.
    G_func.compile_jit(target);

    // Measure execution time (kernel only).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize G_func into Buffer G (shape nl x ni).
    G_func.realize(G);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix G to stderr.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // G[ii][jj] in C => G(jj, ii) in Halide
                std::cerr << G(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds to stdout with 6 decimal places,
    // matching the style of the gemm.cpp example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
